async function loadUser(id: number): Promise<any> {
  const response = await fetch(`/api/users/${id}`);
  if (!response.ok) {
    throw new Error(`bad status ${response.status}`);
  }
  const user = await response.json();
  const orgResponse = await fetch(`/api/orgs/${user.orgId}`);
  const org = await orgResponse.json();
  user.org = org;
  return user;
}

async function loadUsers(ids: number[]): Promise<any[]> {
  const results = await Promise.all(
    ids.map(async (id) => {
      const user = await loadUser(id);
      return user;
    })
  );
  return results;
}

module.exports = { loadUser, loadUsers };
